@router.delete("/infrastructure/clusters/{cluster_id}/worker-nodes/{node_id}")
async def decommission_worker_node(
    cluster_id: str,
    node_id: PydanticObjectId,
    current_user: User = Depends(get_current_user)
):
    cluster = await ClusterDocument.find_one(
        ClusterDocument.cluster_id == cluster_id,
        ClusterDocument.owner_tenant_id == current_user.tenant_id
    )
    if not cluster:
        raise HTTPException(status_code=403, detail="Cluster not found or access denied")

    node = await WorkerNodeDocument.find_one(
        WorkerNodeDocument.id == node_id,
        WorkerNodeDocument.cluster_id == cluster_id
    )
    if not node:
        raise HTTPException(status_code=404, detail="Worker node not found in target cluster")

    await node.delete()
    return {"status": "decommissioned", "node_id": str(node_id), "cluster_id": cluster_id}
